<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['add'])){$n=strtoupper(trim($_POST['slot_number']));$loc=trim($_POST['location']);$stmt=$mysqli->prepare("INSERT INTO slots(slot_number,location,status) VALUES(?,?,'available')");$stmt->bind_param('ss',$n,$loc);if($stmt->execute())flash('success','Slot added.');else flash('error','Slot number already exists.');}elseif(isset($_POST['status'])){$id=(int)$_POST['id'];$status=$_POST['status']==='available'?'available':'maintenance';$stmt=$mysqli->prepare('UPDATE slots SET status=? WHERE id=?');$stmt->bind_param('si',$status,$id);$stmt->execute();flash('success','Slot status updated.');}header('Location: slots.php');exit;}$slots=$mysqli->query('SELECT * FROM slots ORDER BY slot_number');$page_title='Manage slots';require __DIR__.'/../includes/header.php'; ?>
<h2>Manage parking slots</h2><div class="row g-4"><div class="col-md-4"><div class="card p-3 shadow-sm border-0"><h5>Add a slot</h5><form method="post"><input type="hidden" name="add" value="1"><input class="form-control mb-2" name="slot_number" placeholder="A-11" required><input class="form-control mb-2" name="location" placeholder="Ground floor" required><button class="btn btn-primary">Add slot</button></form></div></div><div class="col-md-8"><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Number</th><th>Location</th><th>Status</th><th></th></tr></thead><tbody><?php while($s=$slots->fetch_assoc()):?><tr><td><?=e($s['slot_number'])?></td><td><?=e($s['location'])?></td><td><?=e($s['status'])?></td><td><?php if(!in_array($s['status'],['reserved','occupied'])):?><form method="post"><input type="hidden" name="id" value="<?=$s['id']?>"><button name="status" value="<?=$s['status']==='available'?'maintenance':'available'?>" class="btn btn-sm btn-outline-secondary">Mark <?=$s['status']==='available'?'maintenance':'available'?></button></form><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
